(()=>{const panel=document.querySelector('#training-animation'),button=document.querySelector('#pause-training');if(!panel||!button)return;let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;function sync(){panel.classList.toggle('animation-paused',paused);button.setAttribute('aria-pressed',String(paused));button.textContent=paused?'Play animation':'Pause animation'}button.addEventListener('click',()=>{paused=!paused;sync()});sync()})();
